module top_module (
  input clk,
  input load,
  input [1023:0] data,
  output reg [1023:0] q
);

  // Intermediate register to hold the next state of the cells
  reg [1023:0] next_q;

  // Combinational logic to calculate the next state based on the current state
  always @(*) begin
    integer i;
    for (i = 0; i < 1024; i = i + 1) begin
      if (i == 0) begin
        // Left boundary: q[-1] is considered as 0
        next_q[i] = q[i+1];
      end else if (i == 1023) begin
        // Right boundary: q[1024] is considered as 0
        next_q[i] = q[i-1];
      end else begin
        next_q[i] = q[i-1] ^ q[i+1];
      end
    end
  end

  // Sequential logic to update the state on the rising edge of the clock
  always @(posedge clk) begin
    if (load) begin
      q <= data;
    end else begin
      q <= next_q;
    end
  end

endmodule

