module fsm (
	input clk,
	input reset,
	input l,
	input n,
	output reg q);

	parameter Y=0, Z=1, S1=2, S2=3, S3=4, S4=5;
	reg [2:0] state, next;

	always @(posedge clk) begin
		if (reset) state <= Y;
		else state <= next;
	end

	always_comb begin
		case (state)
			Y: next = l ? Z : Y;
			Z: next = n ? S1 : S2;
			S1: next = n ? S2 : S3;
			S2: next = n ? S3 : S4;
			S3: next = n ? S1 : Y;
			S4: next = l ? Z : Y;
			default: next = 'x;
		endcase
	end

	assign q = (state == S3 && n);

endmodule

