module fsm (
	input clk,
	input reset,
	input u,
	input v,
	output reg q);

	parameter I=0, J=1, K1=2, K2=3, K3=4, K4=5;
	reg [2:0] state, next;

	always @(posedge clk) begin
		if (reset) state <= I;
		else state <= next;
	end

	always_comb begin
		case (state)
			I: next = u ? J : I;
			J: next = v ? K1 : K2;
			K1: next = v ? K2 : K3;
			K2: next = v ? K3 : K4;
			K3: next = u ? J : I;
			K4: next = u ? J : I;
			default: next = 'x;
		endcase
	end

	assign q = (state == K2 && !v);

endmodule

