module binary_counter
    (
		input clk, 
		input rst_n, 
		input enable,
		output reg [3:0] count
    );

	always @(posedge clk or negedge rst_n)
	begin
		if (!rst_n)
			count <= 4'b0000;
		else if (enable)
			count <= count + 1;
	end

endmodule

