module elevator (
	input clk,
	input resetn,
	input up,
	input down,
	output reg at_floor);

	parameter IDLE=0, MOVING_UP=1, MOVING_DOWN=2, AT_FLOOR=3;
	reg [1:0] state, next_state;

	always @(posedge clk) begin
		if (~resetn) state <= IDLE;
		else state <= next_state;
	end

	always_comb begin
		case (state)
			IDLE: next_state = up ? MOVING_UP : (down ? MOVING_DOWN : IDLE);
			MOVING_UP: next_state = AT_FLOOR;
			MOVING_DOWN: next_state = AT_FLOOR;
			AT_FLOOR: next_state = IDLE;
			default: next_state = IDLE;
		endcase
	end

	always @(state) begin
		case (state)
			AT_FLOOR: at_floor = 1;
			default: at_floor = 0;
		endcase
	end
endmodule

