description:
Design a control unit module for a processor that decodes instruction opcodes and function codes to generate control signals for various operations. The module takes a 2-bit opcode, a 6-bit function code, and a 4-bit register identifier as inputs and outputs control signals for writing to registers, memory operations, ALU operations, and instruction branching. It includes a state decoding mechanism that determines control signals based on the input values, enabling functionalities such as ALU operation selection and register writes. Additionally, it features conditions for special operations based on specific function codes, provides feedback on whether a write operation should occur, and manages program counter (PC) operations based on the register identifier.
module top_module(input [1:0] op,input [5:0] funct,input [3:0]rd,
                    output reg [1:0] flagw,output wire pcs,output wire regw,
                    output wire memw,output wire memtoreg,output wire alusrc,
                    output wire [1:0] immsrc,output wire [1:0] regsrc,output reg[1:0] alucontrol ,output wire nowrite
                    );

code:
module top_module(input [1:0] op,input [5:0] funct,input [3:0]rd,
                    output reg [1:0] flagw,output wire pcs,output wire regw,
                    output wire memw,output wire memtoreg,output wire alusrc,
                    output wire [1:0] immsrc,output wire [1:0] regsrc,output reg[1:0] alucontrol ,output wire nowrite
                    );reg [9:0] control;
  wire aluop;
  wire branch;
  always @*
  case(op)
    2'b00: if(funct[5]) control=10'b0001001001;   
           else         control=10'b0000001001;   
    2'b01: if(funct[0]) control=10'b0101011000;   
           else         control=10'b0011010100;   
    2'b10:              control=10'b1001100010;   
	 default:control=10'bxxxxxxxxxx;
   endcase
  assign {branch,memtoreg,memw,alusrc,immsrc,regw,regsrc,aluop} = control; 
  always @*
  if(aluop)begin
  case(funct[4:1])
    4'd4 :  alucontrol=0;   
    4'd2 :  alucontrol=1;   
    4'd0 :  alucontrol=2;   
    4'd12:  alucontrol=3;   
    4'd10:  alucontrol=1;   
    default:alucontrol=2'bxx;
  endcase
   flagw[1]=funct[0];        
   flagw[0] = funct[0] & (alucontrol == 0 | alucontrol == 1);     
  end
else begin          
   flagw=0;
   alucontrol=0; 
 end   
 assign pcs =((rd == 15) & regw) | branch ;        
 assign nowrite = (funct[4:1]==10);       
endmodule

