module gray_code_counter(CLK, RST, Gray_out);
input CLK, RST;
output [2:0] Gray_out;
reg [2:0] binary_counter;
reg [2:0] Gray_out;

always@(posedge CLK or posedge RST) begin
    if (RST)
        binary_counter <= 3'b000;
    else
        binary_counter <= binary_counter + 1;
end

always@(*) begin
    Gray_out = binary_counter ^ (binary_counter >> 1);
end

endmodule

