module fsm (
        input clk,
        input reset,
        input f,
        output reg out);parameter L0=0, L1=1, L2=2, L3=3, L4=4;
	reg [2:0] state, next;

	always @(posedge clk)
		if (reset)
			state <= L0;
		else 
			state <= next;


	always_comb begin
		case(state)
			L0: next = f ? L1 : L2;
			L1: next = f ? L4 : L3;
			L2: next = f ? L1 : L3;
			L3: next = f ? L4 : L0;
			L4: next = f ? L0 : L2;
			default: next = 'x;
		endcase
	end

	assign out = (state == L1 || state == L2 || state == L4);

endmodule

