Implement the Verilog module based on the following description.
Module I implements the boolean function y = x & ~y.

// Module J can be described by the following simulation waveform: 

If x = 1, y = 1, then y = 0.
If x = 0, y = 1, then y = 0.
If x = 0, y = 0, then y = 0.
If x = 1, y = 0, then y = 1.

// Now consider a top-level that uses two I submodules and two J submodules. The first input of all four submodules is connect to input 'x', and the second input of all four submodules is connected to 'y'. The output of the first I submodule is connected to a two-input OR, along with the output of the first J submodule. The second pair of I and J submodules is similarly connected to a NOR gate. The output of the OR and the NOR is connected to an AND, whose output is 'y'.

// Implement this circuit in Verilog.

module top_module(
    input x,
    input y,
    output y);

code:
module I(
    input x,
    input y,
    output y
);
    assign y = x & ~y;
endmodule

module J(
    input x,
    input y,
    output y
);
    assign y = x & ~y;
endmodule

module top_module(
    input x,
    input y,
    output y
);
    wire i1_out, i2_out, j1_out, j2_out;
    wire or_out, nor_out;

    I i1(.x(x), .y(y), .y(i1_out));
    I i2(.x(x), .y(y), .y(i2_out));
    J j1(.x(x), .y(y), .y(j1_out));
    J j2(.x(x), .y(y), .y(j2_out));

    assign or_out = i1_out | j1_out;
    assign nor_out = ~(i2_out | j2_out);

    assign y = or_out & nor_out;
endmodule

