  assign MemClk = 0; 
  assign RamCRE = 0; 
  reg [7:0] data_to_write; 
  assign MemDB = MemOE ? {data_to_write, data_to_write} : 16'bz; 
  reg [1:0] cycles; 
  reg r_read_a; 
  always @(posedge clk) begin 
  if (!busy) begin 
  if (read_a || read_b || write) begin 
  MemAdr <= addr[23:1]; 
  RamUB <= !(addr[0] != 0); 
  RamLB <= !(addr[0] == 0); 
  RamCS <= 0; 
