  cycles <= 0; 
  r_read_a <= read_a; 
  end else begin 
  MemOE <= 1; 
  MemWR <= 1; 
  RamCS <= 1; 
  RamUB <= 1; 
  RamLB <= 1; 
  busy <= 0; 
  cycles <= 0; 
