  MemOE <= 1; 
  MemWR <= 1; 
  RamCS <= 1; 
  RamUB <= 1; 
  RamLB <= 1; 
  busy <= 0; 
  cycles <= 0; 
  end else begin 
  cycles <= cycles + 1; 
  end 
  end 
  end 
