            mem_read <= 0;          // Initialize mem_read on reset
            mem_write_data <= 0;    // Initialize mem_write_data on reset
        end else begin
            if (cpu_read) begin
                mem_address <= cpu_address;
                mem_read <= 1;
                cpu_read_data_reg <= mem_read_data;
            end else begin
                mem_address <= cpu_address;
                mem_read <= 0;
                mem_write_data <= cpu_write_data;  // Use mem_write_data directly
            end
        end
    end

    assign cpu_read_data = cpu_read_data_reg;

endmodule

