module top_module(
    input [3:0] A,
    input [3:0] B,
    input C,
    input O,
    output reg [4:0] S
);wire [3:0] B_neg;
    wire [4:0] sum;

    assign B_neg = (~B) + 1;

    assign sum = (C == 0) ? A + B : A + B_neg;

    always @(*) begin
        if (O == 1 && sum[4] == 1) begin
            S = ~sum + 1;
        end else begin
            S = sum;
        end
    end

endmodule

module top_module(CLK, EN, TE, ENCLK);input CLK, EN, TE;
  output ENCLK;

  reg ENCLK_reg;

  always @(posedge CLK or negedge TE) begin
    if (TE == 0) begin
      if (EN == 1) begin
        ENCLK_reg <= CLK;
      end else begin
        ENCLK_reg <= 0;
      end
    end else begin
      if (TE == 1) begin
        ENCLK_reg <= 1;
      end else begin
        ENCLK_reg <= 0;
      end
    end
  end

  assign ENCLK = ENCLK_reg;

endmodule

module top_module(
  input                clk,
  input                rst_n,
  input                select,
  output reg  [63:0]   Q
);reg [31:0] reg1, reg2;
  reg [5:0] lfsr;

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      reg1 <= 0;
      reg2 <= 0;
      lfsr <= 0;
      Q <= 0;
    end else begin
      if (select) begin
        // LFSR mode
        lfsr[5] <= lfsr[4] ^ lfsr[0];
        lfsr[4] <= lfsr[3];
        lfsr[3] <= lfsr[2];
        lfsr[2] <= lfsr[1];
        lfsr[1] <= lfsr[0];
        lfsr[0] <= lfsr[5];
        Q <= {lfsr, lfsr};
      end else begin
        // Register mode
        reg1 <= {reg1[30:0], reg2[31]};
        reg2 <= {reg2[30:0], reg1[31]};
        Q <= {reg2, reg1};
      end
    end
  end

endmodule

