module full_adder_4bit (
    input wire [3:0] A,
    input wire [3:0] B,
    input wire Cin,
    output wire [3:0] Sum,
    output wire Cout
);

    wire C1, C2, C3;

    full_adder fa0 (.A(A[0]), .B(B[0]), .Cin(Cin), .Sum(Sum[0]), .Cout(C1));
    full_adder fa1 (.A(A[1]), .B(B[1]), .Cin(C1), .Sum(Sum[1]), .Cout(C2));
    full_adder fa2 (.A(A[2]), .B(B[2]), .Cin(C2), .Sum(Sum[2]), .Cout(C3));
    full_adder fa3 (.A(A[3]), .B(B[3]), .Cin(C3), .Sum(Sum[3]), .Cout(Cout));

endmodule

module full_adder (
    input wire A,
    input wire B,
    input wire Cin,
    output wire Sum,
    output wire Cout
);

    assign Sum = A ^ B ^ Cin;
    assign Cout = (A & B) | (B & Cin) | (A & Cin);

endmodule

module top_module(
    input D,
    output Q,
    output Q_N,
    input SET_B,
    input SCD,
    input SCE,
    input CLK,
    input VPB,
    input VPWR,
    input VGND,
    input VNB
);reg Q_reg, Q_N_reg;
    wire Q_wire, Q_N_wire;

    // SET_B control logic
    always @ (SET_B) begin
        if (SET_B) begin
            Q_reg <= 1;
            Q_N_reg <= 0;
        end
    end

    // Data signal logic
    always @ (posedge CLK) begin
        if (!SET_B) begin
            Q_reg <= D;
            Q_N_reg <= ~D;
        end
    end

    // Output signals
    assign Q_wire = Q_reg;
    assign Q_N_wire = Q_N_reg;
    assign Q = (SCD && !SCE) ? Q_wire : Q_reg;
    assign Q_N = (SCD && !SCE) ? Q_N_wire : Q_N_reg;

endmodule

