      3'b010: out = a & b;
      3'b011: out = a | b;
      3'b100: out = a ^ b;
      default: out = 8'h00;
    endcase
  end

  always @(posedge reg_write) begin
    if (reg_write) begin
      result <= out;  // Update only once based on out
    end
  end

endmodule

