code:
module elevator_controller (
	input clk,
	input resetn,
	input up,
	input down,
	output reg [1:0] direction);

	parameter IDLE=0, GOING_UP=1, GOING_DOWN=2;
	reg [1:0] state, next_state;

	always @(posedge clk) begin
		if (~resetn) state <= IDLE;
		else state <= next_state;
	end

	always_comb begin
		case (state)
			IDLE: 
				if (up) next_state = GOING_UP;
				else if (down) next_state = GOING_DOWN;
				else next_state = IDLE;
			GOING_UP: next_state = up ? GOING_UP : IDLE;
			GOING_DOWN: next_state = down ? GOING_DOWN : IDLE;
			default: next_state = IDLE;
		endcase
	end

	always @(state) begin
		case (state)
			IDLE: direction = 2;
			GOING_UP: direction = 1;
			GOING_DOWN: direction = 0;
			default: direction = 2;
		endcase
	end
endmodule

