			3'b000: H = 1'b1;
			3'b001: H = 1'b0;
			3'b010: H = 1'b1;
			3'b011: H = 1'b0;
			3'b100: H = 1'b0;
			3'b101: H = 1'b1;
			3'b110: H = 1'b1;
