		input rst,
		input freeze,
		input flush,
		input [31:0] PC_in,
		input [31:0] instruction_in,


		output reg [31:0] PC,
		output reg [31:0] instruction
		);always @(posedge clk, posedge rst) begin
			if(rst)
				{PC, instruction} <= 64'b0;
			else begin  
