module top_module (
    input [4:1] y,
    input g,
    output reg Y2,
    output reg Y3
);

    always @(*) begin
        // Y2 corresponds to the transition to state X
        Y2 = (y[1] & ~g) | (y[4] & ~g);

        // Y3 corresponds to the transition to state Y
        Y3 = (y[1] & g) | (y[2] & g);
    end

endmodule

description:
Design a circuit that compares two 8-bit binary inputs, `a` and `b`, to determine if they are equal. The module utilizes bitwise XOR to identify differing bits and employs a combination of NOR and NAND logic to derive a single output, `result`, which indicates equality. The output is HIGH when `a` and `b` are equal, and LOW otherwise, serving as a simple equality comparator for 8-bit numbers.
module top_module(
  input [7:0] a,
  input [7:0] b,
  output result
);

