module top_module(Reset_N,Sixty_in,Add,Subtract,Sixty_out,count);input Reset_N;

input Sixty_in;
input Add,Subtract;
reg Add0,Add1;
reg Subtract0,Subtract1;
output Sixty_out;
output[0:5] count;
reg Sixty_out;
reg[0:5] count;
parameter Full_59 = 6'b11_1011;


always@(posedge Sixty_in or posedge Add or posedge Subtract or negedge Reset_N )
begin
	if(!Reset_N)
		begin
			Sixty_out <= 0;
			count <= 0;
		end
		else if(Add)
		begin
			count <= count + 1'b1;
			if(count == Full_59)
				begin
					count <= 0;
				end
		end
	else if(Subtract)
		begin
			count <= count - 1'b1;
			if(count == 6'b11_1111)
				begin
					count <= 6'b11_1011;
				end
		end
	else 
		begin
			Sixty_out <= 0;
			count <= count + 1'b1;
			if(count == Full_59)
				begin
				   Sixty_out <= 1;
					count <= 0;
				end
		end
end

endmodule

description:
Develop a Verilog module for an 8-bit parallel-in serial-out (PISO) shift register with synchronous active high reset.
// (1) reset: Resets the shift register to 8'b00000000 when high.
// (2) load: Loads the shift register with the value on the input data signal when high.
// (3) data: 8-bit input data for loading into the shift register.
// (4) q: The serial output of the shift register.

module piso_shift_register(
    input clk,
    input reset,
    input load,
    input [7:0] data,
    output reg q);

code:
module piso_shift_register(
    input clk,
    input reset,
    input load,
    input [7:0] data,
    output reg q
);

    reg [7:0] shift_reg;

    always @(posedge clk) begin
        if (reset) begin
            // Synchronous reset
            shift_reg <= 8'b00000000;
        end else if (load) begin
            // Load the shift register with data
            shift_reg <= data;
        end else begin
            // Shift right
            shift_reg <= {1'b0, shift_reg[7:1]};
        end
        q <= shift_reg[0];
    end

endmodule

